method Fib (n: nat) returns (r:nat)
    ensures r == fib(n)
{

    if (n == 0) {
        return 1;
    }
    r := 1;
    var next:=2;
    var i := 1;
    while i < n
        invariant 1 <= i <= n
        invariant r == fib(i)
        invariant next == fib(i+1)
    {
        var tmp:=next;
        next:= next + r;
        r:= tmp;
        i:= i + 1;
    }
    assert r == fib(n);
    return r;
}


datatype List<T> = Nil | Cons(head: T, tail: List<T>)

function add(l:List<int>) : int
{
    match l
    case Nil => 0
    case Cons(x, xs) => x + add(xs)
}


method addImp (l: List<int>) returns (s: int)
    ensures s == add(l)
{
    var ll := l;
    s := 0;
    while ll != Nil
        decreases ll
        invariant add(l) == s + add(ll)
        {
            s := s + ll.head;
            ll:= ll.tail;
        }
    assert s == add(l);
}


